// ASLQuizComponent.js - Interactive Hand Sign Quiz for Visual Novel Maker
// Place in: C:\Users\holly\QuietBakery\Scripts\ASLQuizComponent.js
// EMBEDDED VERSION - Images included in script

(function() {
    'use strict';

    // Base64 encoded hand sign images
    const HAND_SIGNS_BASE64 = {
        C: '',
        O: '',
        F: '',
        E: ''
    };

    // Quiz Configuration
    const QUIZ_CONFIG = {
        // Single COFFEE quiz question
        questions: [
            {
                word: "COFFEE",
                signs: ["C", "O", "F", "F", "E", "E"],
                options: ["COFFEE", "COOKIE", "TOFFEE", "OFFICE"],
                correctAnswer: "COFFEE"
            }
        ],
        
        // Positions and styling - ULTRA COMPACT & SHORT
        containerRight: 150,
        containerTop: 50,
        signSize: 30,
        buttonHeight: 22,
        spacing: 3
    };

    // Game state
    let currentQuestionIndex = 0;
    let score = 0;
    let quizActive = false;
    let quizContainer = null;
    let completionCallback = null;

    // Create the quiz component
    window.ASLQuiz = {
        start: function(callback) {
            if (quizActive) return;
            
            currentQuestionIndex = 0;
            score = 0;
            quizActive = true;
            completionCallback = callback || null;
            
            createQuizContainer();
            displayQuestion();
        },
        
        startAndWait: function() {
            // Turn off switch first
            if (typeof $gameSwitches !== 'undefined') {
                $gameSwitches.setValue(1, false);
            }
            
            // Start the quiz
            this.start();
            
            // Create a waiting loop using VNM's interpreter
            if (typeof $gameMap !== 'undefined' && $gameMap._interpreter) {
                var interpreter = $gameMap._interpreter;
                
                // Store original command index
                var waitCommand = function() {
                    if (quizActive) {
                        // Still active, wait more
                        return false; // Not finished waiting
                    } else {
                        // Quiz complete
                        return true; // Finished waiting
                    }
                };
                
                // Set waiting flag
                interpreter.setWaitMode('aslquiz');
            }
        },
        
        stop: function() {
            // Remove blocker
            const blocker = document.getElementById('aslQuizBlocker');
            if (blocker && blocker.parentNode) {
                document.body.removeChild(blocker);
            }
            
            // Remove quiz container
            if (quizContainer && quizContainer.parentNode) {
                document.body.removeChild(quizContainer);
            }
            quizContainer = null;
            quizActive = false;
            
            // Call completion callback if exists
            if (completionCallback) {
                completionCallback();
                completionCallback = null;
            }
            
            // Set game switch to signal completion
            if (typeof $gameSwitches !== 'undefined') {
                $gameSwitches.setValue(1, true); // Turn on switch #1
            }
            
            console.log('Quiz stopped. Switch 1 set to TRUE');
            
            // Clear wait mode if it exists
            if (typeof $gameMap !== 'undefined' && $gameMap._interpreter) {
                var interpreter = $gameMap._interpreter;
                if (interpreter._waitMode === 'aslquiz') {
                    interpreter._waitMode = '';
                }
            }
        },
        
        isActive: function() {
            return quizActive;
        },
        
        getTotalQuestions: function() {
            return QUIZ_CONFIG.questions.length;
        }
    };

    function createQuizContainer() {
        // Remove existing container if any
        if (quizContainer && quizContainer.parentNode) {
            document.body.removeChild(quizContainer);
        }

        // Create blocking overlay to prevent VN progression
        const blocker = document.createElement('div');
        blocker.id = 'aslQuizBlocker';
        blocker.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 9997;
            background-color: transparent;
            pointer-events: auto;
        `;
        
        // Prevent all clicks on the blocker from reaching VN
        blocker.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            return false;
        }, true);
        
        blocker.addEventListener('mousedown', function(e) {
            e.stopPropagation();
            e.preventDefault();
            return false;
        }, true);
        
        document.body.appendChild(blocker);

        quizContainer = document.createElement('div');
        quizContainer.id = 'aslQuizContainer';
        quizContainer.style.cssText = `
            position: fixed;
            right: ${QUIZ_CONFIG.containerRight}px;
            top: ${QUIZ_CONFIG.containerTop}px;
            width: 150px;
            background-color: rgba(255, 255, 255, 0.95);
            border: 2px solid #8B6F47;
            border-radius: 6px;
            padding: 6px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.4);
            z-index: 9998;
            font-family: Arial, sans-serif;
        `;

        document.body.appendChild(quizContainer);
    }

    function displayQuestion() {
        if (!quizContainer) return;
        
        const question = QUIZ_CONFIG.questions[currentQuestionIndex];
        
        // Clear container
        quizContainer.innerHTML = '';

        // Add header
        const header = document.createElement('div');
        header.style.cssText = `
            text-align: center;
            font-size: 10px;
            font-weight: bold;
            color: #8B6F47;
            margin-bottom: 4px;
            padding-bottom: 3px;
            border-bottom: 1px solid #8B6F47;
        `;
        header.textContent = `ASL Quiz`;
        quizContainer.appendChild(header);

        // Add instruction
        const instruction = document.createElement('div');
        instruction.style.cssText = `
            text-align: center;
            font-size: 8px;
            color: #333;
            margin-bottom: 4px;
        `;
        instruction.textContent = 'What word?';
        quizContainer.appendChild(instruction);

        // Add hand signs container
        const signsContainer = document.createElement('div');
        signsContainer.style.cssText = `
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 2px;
            margin-bottom: 5px;
            padding: 3px;
            background-color: #f5f5f5;
            border-radius: 3px;
        `;

        // Add each hand sign using embedded base64
        question.signs.forEach((letter, index) => {
            const signImg = document.createElement('img');
            signImg.src = `data:image/png;base64,${HAND_SIGNS_BASE64[letter]}`;
            signImg.alt = letter;
            signImg.style.cssText = `
                width: ${QUIZ_CONFIG.signSize}px;
                height: ${QUIZ_CONFIG.signSize}px;
                object-fit: contain;
                border: 1px solid #ddd;
                border-radius: 4px;
                background-color: white;
            `;
            
            signsContainer.appendChild(signImg);
        });

        quizContainer.appendChild(signsContainer);

        // Add options label
        const optionsLabel = document.createElement('div');
        optionsLabel.style.cssText = `
            text-align: center;
            font-size: 8px;
            color: #666;
            margin-bottom: 3px;
        `;
        optionsLabel.textContent = 'Choose:';
        quizContainer.appendChild(optionsLabel);

        // Add answer buttons
        const buttonsContainer = document.createElement('div');
        buttonsContainer.style.cssText = `
            display: flex;
            flex-direction: column;
            gap: ${QUIZ_CONFIG.spacing}px;
        `;

        question.options.forEach(option => {
            const button = document.createElement('button');
            button.textContent = option;
            button.style.cssText = `
                width: 100%;
                height: ${QUIZ_CONFIG.buttonHeight}px;
                background-color: #8B6F47;
                color: white;
                border: none;
                border-radius: 3px;
                font-size: 9px;
                font-weight: bold;
                cursor: pointer;
                transition: all 0.2s;
                box-shadow: 0 1px 2px rgba(0,0,0,0.2);
            `;

            button.addEventListener('mouseenter', function() {
                button.style.backgroundColor = '#6B5638';
                button.style.transform = 'translateY(-1px)';
            });

            button.addEventListener('mouseleave', function() {
                button.style.backgroundColor = '#8B6F47';
                button.style.transform = 'translateY(0)';
            });

            button.addEventListener('click', function() {
                handleAnswer(option, question.correctAnswer, button);
            });

            buttonsContainer.appendChild(button);
        });

        quizContainer.appendChild(buttonsContainer);
    }

    function handleAnswer(selectedAnswer, correctAnswer, buttonElement) {
        const isCorrect = selectedAnswer === correctAnswer;
        
        // Disable all buttons
        const allButtons = quizContainer.querySelectorAll('button');
        allButtons.forEach(btn => {
            btn.disabled = true;
            btn.style.cursor = 'not-allowed';
            btn.style.opacity = '0.6';
        });

        // Show feedback on clicked button
        if (isCorrect) {
            score++;
            buttonElement.style.backgroundColor = '#4CAF50';
            buttonElement.style.opacity = '1';
            buttonElement.textContent = '✓ ' + selectedAnswer;
            
            if (typeof AudioManager !== 'undefined') {
                AudioManager.playSe({name: 'Decision1', volume: 90, pitch: 100, pan: 0});
            }
            
            // Success - close quiz after brief delay
            setTimeout(function() {
                // Remove blocker
                const blocker = document.getElementById('aslQuizBlocker');
                if (blocker && blocker.parentNode) {
                    document.body.removeChild(blocker);
                }
                
                // Remove container
                if (quizContainer && quizContainer.parentNode) {
                    document.body.removeChild(quizContainer);
                }
                quizContainer = null;
                quizActive = false;
                
                // Set switch to signal completion
                if (typeof $gameSwitches !== 'undefined') {
                    $gameSwitches.setValue(1, true);
                }
                
                console.log('Quiz completed successfully! Switch 1 set to TRUE');
            }, 800);
            
        } else {
            buttonElement.style.backgroundColor = '#f44336';
            buttonElement.style.opacity = '1';
            buttonElement.textContent = '✗ ' + selectedAnswer;
            
            if (typeof AudioManager !== 'undefined') {
                AudioManager.playSe({name: 'Buzzer1', volume: 90, pitch: 100, pan: 0});
            }
            
            // Show "Try Again" message
            const wrongMsg = document.createElement('div');
            wrongMsg.style.cssText = `
                text-align: center;
                font-size: 9px;
                font-weight: bold;
                color: #f44336;
                margin-top: 6px;
                padding: 5px;
                background-color: #ffebee;
                border-radius: 3px;
            `;
            wrongMsg.textContent = '❌ Try Again!';
            quizContainer.appendChild(wrongMsg);
            
            // Wrong - show message then reset quiz
            setTimeout(function() {
                console.log('Resetting quiz...');
                displayQuestion();
            }, 1500);
        }
    }

    console.log('ASL Quiz Component loaded. Use ASLQuiz.start() to begin.');

})();

